        "quick-send-4": () => KLITE_RPMod.panels.TOOLS.handleQuickSend(4),
        "quick-send-5": () => KLITE_RPMod.panels.TOOLS.handleQuickSend(5),
        // Trigger narrator
        "narrator": () => KLITE_RPMod.panels.TOOLS.triggerNarrator(),
        // Quick Actions (from ADV)
