  // src/onboarding/guide.js
  var STORE_KEY2 = "KLITE.guide.chapter";
  function savedChapter() {
    try {
      return localStorage.getItem(STORE_KEY2);
    } catch (_) {
      return null;
    }
  }
  function saveChapter(id) {
    try {
      localStorage.setItem(STORE_KEY2, id);
    } catch (_) {
    }
  }
  var spot = null;
  function clearHighlight() {
    if (!spot) return;
    clearTimeout(spot.timer);
    document.removeEventListener("keydown", spot.onKey, true);
    document.removeEventListener("pointerdown", spot.onDown, true);
    spot.nodes.forEach((n) => n.remove());
    spot = null;
  }
  function highlight(target, note) {
    clearHighlight();
    let node = null;
    try {
      node = typeof target === "function" ? target() : typeof target === "string" ? document.querySelector(target) : target;
    } catch (_) {
    }
    const visible = node && node.getClientRects && node.getClientRects().length > 0;
    const nodes = [];
    const bubble = el("div", { class: "rpm-themed rpm-spot-note", role: "status" }, [
      el("span", { text: visible ? note : "That part of the screen is hidden right now. Open the RPmod panels with the RPmod button in the top bar and try again." })
    ]);
    if (visible) {
      try {
        node.scrollIntoView({ block: "nearest", inline: "nearest" });
      } catch (_) {
      }
      const r = node.getBoundingClientRect();
      const pad = 6;
      const ring = el("div", {
        class: "rpm-themed rpm-spot-ring",
        "aria-hidden": "true",
        style: `left:${Math.round(r.left - pad)}px;top:${Math.round(r.top - pad)}px;width:${Math.round(r.width + pad * 2)}px;height:${Math.round(r.height + pad * 2)}px`
      });
      nodes.push(ring);
      const below = r.bottom + 90 < (window.innerHeight || 768);
      bubble.style.left = Math.round(Math.max(8, Math.min(r.left, (window.innerWidth || 1024) - 300))) + "px";
      bubble.style.top = Math.round(below ? r.bottom + pad + 8 : Math.max(8, r.top - pad - 56)) + "px";
    } else {
      bubble.style.left = "50%";
      bubble.style.top = "40%";
      bubble.style.transform = "translateX(-50%)";
    }
    nodes.push(bubble);
    nodes.forEach((n) => document.body.appendChild(n));
    const onKey = (e) => {
      if (e.key === "Escape") clearHighlight();
    };
    const onDown = () => clearHighlight();
    spot = { nodes, onKey, onDown, timer: setTimeout(clearHighlight, 6e3) };
    document.addEventListener("keydown", onKey, true);
    setTimeout(() => {
      if (spot && spot.onDown === onDown) document.addEventListener("pointerdown", onDown, true);
    }, 0);
    return !!visible;
  }
  function createGuideView(shell) {
    let current = CHAPTERS.some((c) => c.id === savedChapter()) ? savedChapter() : CHAPTERS[0].id;
    const ctx = {
      open: (id) => {
        try {
          shell.open(id);
        } catch (_) {
        }
      },
      highlight: (target, note) => setTimeout(() => highlight(target, note), 60),
      // after panels/windows opened
      hostCall: (name) => {
        const fn = hostGet(name);
        if (typeof fn === "function") fn();
      },
      navLink: (text) => () => [...document.querySelectorAll("#navbarNavDropdown a.nav-link")].find((a) => a.textContent.trim() === text && a.offsetParent !== null)
    };
    function renderBlock(b) {
      if (b.p) return el("p", { style: "margin:0 0 10px", text: b.p });
      if (b.tip) return el("div", { class: "rpm-card rpm-card-hi", style: "margin:0 0 10px", text: b.tip });
      if (b.list) return el("ul", { style: "margin:0 0 10px;padding-left:20px" }, b.list.map((t) => el("li", { style: "margin-bottom:4px", text: t })));
      if (b.table) {
        const [headRow, ...rows] = b.table;
        return el("table", { class: "rpm-guide-table" }, [
          el("thead", null, [el("tr", null, headRow.map((h) => el("th", { text: h })))]),
          el("tbody", null, rows.map((r) => el("tr", null, [el("td", null, [el("code", { text: r[0] })]), el("td", { text: r[1] })])))
        ]);
      }
      return null;
    }
    function render(box) {
      clear(box);
      const idx = Math.max(0, CHAPTERS.findIndex((c) => c.id === current));
      const ch = CHAPTERS[idx];
      const go = (id) => {
        current = id;
        saveChapter(id);
        render(box);
      };
      const toc = el(
        "nav",
        { class: "rpm-guide-toc", "aria-label": "Guide chapters" },
        CHAPTERS.map((c, i) => el("button", {
          type: "button",
          class: "rpm-guide-toc-item",
          "aria-current": c.id === ch.id ? "page" : null,
          text: `${i + 1}. ${c.title}`,
          onclick: () => go(c.id)
        }))
      );
      const article = el("article", { class: "rpm-guide-body", "data-chapter": ch.id }, [
        el("div", { class: "rpm-muted", text: `Chapter ${idx + 1} of ${CHAPTERS.length}` }),
        el("h2", { class: "rpm-guide-title", text: ch.title }),
        ...ch.blocks.map(renderBlock).filter(Boolean)
      ]);
      if (ch.show && ch.show.length) {
        article.appendChild(el("div", { class: "rpm-label", text: "Show me" }));
        article.appendChild(el("div", { class: "rpm-row", style: "flex-wrap:wrap" }, ch.show.map((s) => el("button", { type: "button", class: "btn btn-primary rpm-btn", "data-show": s.label, text: "👁 " + s.label, onclick: () => {
          try {
            s.run(ctx);
          } catch (e) {
            console.error("[RPmod guide]", e);
          }
        } }))));
      }
      article.appendChild(el("div", { class: "rpm-row rpm-guide-nav" }, [
        el("button", { type: "button", class: "btn btn-primary rpm-btn", text: "← Back", disabled: idx === 0 ? "disabled" : null, onclick: () => go(CHAPTERS[idx - 1].id) }),
        el("span", { class: "rpm-grow" }),
        idx < CHAPTERS.length - 1 ? el("button", { type: "button", class: "btn btn-primary rpm-btn rpm-lg", text: "Next: " + CHAPTERS[idx + 1].title + " →", onclick: () => go(CHAPTERS[idx + 1].id) }) : el("button", { type: "button", class: "btn btn-primary rpm-btn rpm-lg", text: "Done", onclick: () => shell.close("guide") })
      ]));
      box.appendChild(el("div", { class: "rpm-guide" }, [toc, article]));
    }
    return {
      id: "guide",
      title: "RPmod Guide",
      place: "window",
      window: { width: 680, height: 560, minWidth: 320, minHeight: 280 },
      mount: render,
      update: render,
      goTo: (id) => {
        if (CHAPTERS.some((c) => c.id === id)) {
          current = id;
          saveChapter(id);
        }
      }
    };
  }

  // src/onboarding/quickStart.js
  var extensions = [];
  var mode = null;
  function quickStartMode() {
    return mode;
  }
  function registerQuickStartExtension(ext) {
    if (!ext || !ext.id || extensions.some((e) => e.id === ext.id)) return;
    extensions.push(ext);
    if (mode === "api") window.quickStartExtensions.register(ext);
  }
  function installQuickStartHooks() {
    if (mode) return true;
    const api = window.quickStartExtensions;
    if (api && typeof api.register === "function") {
      extensions.forEach((e) => api.register(e));
      mode = "api";
      return true;
    }
    const show = hostGet("showQuickStartPopup");
    const apply = hostGet("applyQuickStartSelection");
    if (typeof show !== "function" || typeof apply !== "function") return false;
    if (show.__rpmodWrapped) {
      mode = "adapter";
      return true;
    }
    const wrappedShow = function() {
      const ret = show.apply(this, arguments);
      try {
        renderSections();
      } catch (e) {
        console.error("[RPmod] Quick Start extension render failed", e);
      }
      return ret;
    };
    wrappedShow.__rpmodWrapped = true;
    const wrappedApply = async function() {
      await apply.apply(this, arguments);
      await applyExtensions();
    };
    const clearAll = hostGet("clearAllQuickStartSelections");
    if (!hostSet("showQuickStartPopup", wrappedShow) || !hostSet("applyQuickStartSelection", wrappedApply)) return false;
    if (typeof clearAll === "function") {
      hostSet("clearAllQuickStartSelections", function() {
        clearAll.apply(this, arguments);
        extensions.forEach((e) => {
          try {
            e.clear();
          } catch (_) {
          }
        });
      });
    }
    mode = "adapter";
    return true;
  }
  async function applyExtensions() {
    const errors = [];
    for (const ext of extensions) {
      if (!safe(() => ext.hasSelection())) continue;
      try {
        await ext.apply();
      } catch (e) {
        console.error("[RPmod] Quick Start extension failed:", ext.id, e);
        errors.push(`${ext.label}: ${e && e.message ? e.message : e}`);
      }
    }
    if (errors.length) {
      const handleError = hostGet("handleError");
      if (typeof handleError === "function") handleError(errors.join("\n"));
      else console.error(errors.join("\n"));
    }
  }
  function safe(fn) {
    try {
      return fn();
    } catch (_) {
      return false;
    }
  }
  function renderSections() {
    const popup = hostGet("popupUtils");
    const host = popup && popup.contentElem;
    if (!host) return;
    const contents = host.firstElementChild || host;
    const rerender = () => {
      const s = hostGet("showQuickStartPopup");
      if (typeof s === "function") s();
    };
    for (const ext of extensions) {
      const section = document.createElement("div");
      section.dataset.rpmodQuickstart = ext.id;
      section.style.cssText = "width:100%;display:flex;flex-direction:column;padding:10px;gap:8px;";
      const head = document.createElement("div");
      head.style.cssText = "display:flex;align-items:center;gap:8px;";
      const title = document.createElement("span");
      title.style.fontWeight = "bold";
      title.textContent = ext.label;
      head.appendChild(title);
      if (ext.helpText) {
        const help = document.createElement("span");
        help.className = "helpicon";
        help.textContent = "?";
        const tip = document.createElement("span");
        tip.className = "helptext";
        tip.textContent = ext.helpText;
        help.appendChild(tip);
        head.appendChild(help);
      }
      section.appendChild(head);
      const body = document.createElement("div");
      body.style.cssText = "width:100%;display:flex;flex-direction:column;gap:8px;";
      section.appendChild(body);
      try {
        ext.render(body, rerender);
      } catch (e) {
        console.error("[RPmod] Quick Start section failed:", ext.id, e);
        continue;
      }
      contents.appendChild(section);
    }
  }
  function quickStartTile(name, onClick, empty) {
    const tile = document.createElement("span");
    tile.className = "containAndScaleImage tile quick_start_preview_tile" + (empty ? " quick_start_preview_tile_empty" : "");
    tile.style.backgroundImage = empty ? "url('/static/img/folder.svg')" : "var(--img_esobold)";
    tile.title = name;
    const label = document.createElement("b");
    label.textContent = name;
    tile.appendChild(label);
    if (onClick) tile.addEventListener("click", onClick);
    return tile;
  }

  // src/onboarding/onboarding.js
  var WELCOME_KEY = "KLITE.onboarding.welcome";
  function initOnboarding() {
    "use strict";
    if (window.KLITE_RPMod_Onboarding) return;
    let guide = null;
    const api = {
      openGuide(chapterId) {
        const sh = window.KLITE_RPMod_Shell;
        if (!sh || !guide) return false;
        if (chapterId) guide.goTo(chapterId);
        if (sh.isOpen("guide")) sh.refresh(["guide"]);
        return sh.open("guide");
      },
      openQuickStart() {
        const fn = hostGet("showQuickStartPopup");
        if (typeof fn === "function") {
          fn();
          return true;
        }
        return false;
      },
      highlight,
      clearHighlight,
      quickStartMode,
      legacySaveHookInstalled: () => legacyInstalled
    };
    window.KLITE_RPMod_Onboarding = api;
    installLegacySavePassthrough();
    registerQuickStartExtension(rpmodWorldExtension());
    let qsTries = 0;
    const qsTimer = setInterval(() => {
      if (installQuickStartHooks() || ++qsTries > 240) clearInterval(qsTimer);
    }, 250);
    let shTries = 0;
    const shTimer = setInterval(() => {
      const sh = window.KLITE_RPMod_Shell;
      if (!sh) {
        if (++shTries > 300) clearInterval(shTimer);
        return;
      }
      clearInterval(shTimer);
      guide = createGuideView(sh);
      sh.registerView(guide);
      sh.addDockAction("left", { id: "guide", title: "RPmod Guide", label: "?", onClick: () => api.openGuide() });
      if (!welcomeDismissed()) sh.registerView(welcomeView(sh, api));
    }, 100);
  }
  function welcomeDismissed() {
    try {
      return localStorage.getItem(WELCOME_KEY) === "dismissed";
    } catch (_) {
      return false;
    }
  }
  function welcomeView(sh, api) {
    return {
      id: "welcome",
      title: "New here?",
      place: "left",
      order: -10,
      mount(box) {
        box.appendChild(el("p", { style: "margin:0 0 8px", text: "RPmod turns Esolite into a tabletop roleplaying game with worlds, quests and dice. Start a session with Esolite's Quick Start, or read the short guide first." }));
        box.appendChild(el("div", { class: "rpm-row", style: "flex-wrap:wrap" }, [
          el("button", { type: "button", class: "btn btn-primary rpm-btn rpm-grow", text: "📖 Open the Guide", onclick: () => api.openGuide("welcome") }),
          el("button", { type: "button", class: "btn btn-primary rpm-btn rpm-grow", text: "▶ Quick Start", onclick: () => api.openQuickStart() })
        ]));
        box.appendChild(el("button", {
          type: "button",
          class: "btn btn-primary rpm-btn rpm-block",
          style: "margin-top:6px",
          text: "Got it — hide this",
          onclick: () => {
            try {
              localStorage.setItem(WELCOME_KEY, "dismissed");
            } catch (_) {
            }
            sh.unregisterView("welcome");
          }
        }));
      }
    };
  }
  var EXAMPLE_ID = "world_example";
  function rpmodWorldExtension() {
    let selection = null;
    let choosing = false;
    const W = () => window.KLITE_RPMod_Worlds;
    return {
      id: "rpmod-world",
      label: "RPmod world (optional)",
      helpText: 'Play in an RPmod world: places, people, quests and combat that the AI game master follows. Confirm enables it for this story. New? Choose the example "Eldoria".',
      hasSelection: () => !!selection,
      clear: () => {
        selection = null;
        choosing = false;
      },
      render(body, rerender) {
        const grid = el("div", { class: "quick_start_preview_grid" });
        grid.appendChild(selection ? quickStartTile(selection.name, () => {
          selection = null;
          rerender();
        }) : quickStartTile("(none selected)", null, true));
        if (selection) grid.firstChild.title = `${selection.name} (click to deselect)`;
        body.appendChild(grid);
        if (choosing) {
          const list = el("div", { style: "display:flex;flex-wrap:wrap;gap:8px" });
          const worlds = W() && W().listWorlds() || [];
          const options = worlds.map((w) => ({ id: w.id, name: w.name || w.id }));
          if (!options.some((o) => o.id === EXAMPLE_ID)) options.unshift({ id: EXAMPLE_ID, name: "Eldoria (example world)", example: true });
          for (const o of options) {
            list.appendChild(el("button", { type: "button", class: "btn btn-primary", text: o.name, onclick: () => {
              selection = o;
              choosing = false;
              rerender();
            } }));
          }
          body.appendChild(list);
        }
        body.appendChild(el("div", { style: "display:flex;gap:10px;flex-wrap:wrap" }, [
          el("button", { type: "button", class: "btn btn-primary", text: choosing ? "Cancel" : "Choose world", onclick: () => {
            choosing = !choosing;
            rerender();
          } }),
          el("button", { type: "button", class: "btn btn-primary", text: "Clear", onclick: () => {
            selection = null;
            choosing = false;
            rerender();
          } }),
          el("button", { type: "button", class: "btn btn-primary", text: "What is RPmod?", onclick: () => {
            const p = hostGet("popupUtils");
            if (p && p.reset) p.reset();
            window.KLITE_RPMod_Onboarding.openGuide("welcome");
          } })
        ]));
      },
      async apply() {
        const A = W();
        if (!A) throw new Error("Worlds engine not loaded");
        const sel = selection;
        if (sel.id === EXAMPLE_ID && !A.hasExample()) await A.loadExample();
        else A.useWorld(sel.id);
        A.enable();
        if (!(A.runtime && A.runtime.playerLocationId)) {
          const first = A.getGraph().nodes.find((n) => n.type === "location");
          if (first) A.moveTo(first.id);
        }
        selection = null;
        try {
          window.KLITE_RPMod_Shell && window.KLITE_RPMod_Shell.open("world");
        } catch (_) {
        }
      }
    };
  }
  var legacyInstalled = false;
  function installLegacySavePassthrough() {
    let legacy = null;
    let tries = 0;
    const timer = setInterval(() => {
      const save = window.generate_savefile, load = window.kai_json_load;
      if (typeof save !== "function" || typeof load !== "function") {
        if (++tries > 300) clearInterval(timer);
        return;
      }
      clearInterval(timer);
      if (!save.__rpmodLegacy) {
        const wrappedSave = function() {
          const obj = save.apply(this, arguments);
          try {
            if (legacy && obj && typeof obj === "object" && !obj.guided_rp) obj.guided_rp = legacy;
          } catch (_) {
          }
          return obj;
        };
        wrappedSave.__rpmodLegacy = true;
        window.generate_savefile = wrappedSave;
      }
      if (!load.__rpmodLegacy) {
        const wrappedLoad = function(storyobj) {
          try {
            legacy = storyobj && storyobj.guided_rp ? storyobj.guided_rp : null;
          } catch (_) {
          }
          return load.apply(this, arguments);
        };
        wrappedLoad.__rpmodLegacy = true;
        window.kai_json_load = wrappedLoad;
      }
      legacyInstalled = true;
    }, 100);
  }

